// Elasticsearch 未授权访问漏洞检测
// FOFA 语法：title="Elasticsearch"
// by Modified from previous code
yakit.AutoInitYakit()
log.setLevel("info")


handleCheck = func(addr, ip){
    isTls = str.IsTLSServer(addr)
    packet = `GET /_cat/ HTTP/1.1
Host: {{params(target)}}
User-Agent: Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/91.0.4472.124 Safari/537.36
Accept-Encoding: gzip, deflate, br
Accept: */*
`
    rsp, req, _ = poc.HTTP(packet, poc.params({"target":addr}), poc.https(isTls), poc.redirectTimes(0), poc.connectTimeout(2))
    if rsp && req {
        hand, body = str.SplitHTTPHeadersAndBodyFromPacket(rsp)
        drsp, derr = str.ParseBytesToHTTPResponse(rsp)
        if derr != nil {
            yakit.Error(string(derr))
            return
        }
        if drsp.StatusCode == 200 && str.Count(string(body), "/_cat/") > 1 && str.Count(string(body), "=^.^=") > 0 {
            risk.NewRisk(
                addr, 
                risk.severity("high"),
                risk.title("Elasticsearch 未授权访问漏洞"),
                risk.title(string(ip)),
                risk.description("攻击者可以在未授权的情况下访问 Elasticsearch 的 _cat 接口，可能获取敏感信息。"),
                risk.solution("配置 Elasticsearch 的访问控制，设置用户名和密码进行身份验证，限制外部访问。"), 
                risk.request(req),
                risk.response(rsp),
                risk.details({"packet":string(packet)})
            )
            yakit.Info("检测到 Elasticsearch 未授权访问漏洞: %v", addr)
        }
    }
    return
}

target = cli.String("Target",cli.setRequired(false))
cli.check()
iptables = cli.LineDict("Targets",cli.setRequired(false))
cli.check()

run = func(iptables) {
    t = 0
    swg := sync.NewSizedWaitGroup(100)
    m = sync.NewMutex()
    for _, ip := range iptables {
        ip, port, _ := str.ParseStringToHostPort(ip)
        addr := str.HostPort(ip, port)
        swg.Add(1)
        go func(addr, ip) {
            defer swg.Done()
            handleCheck(addr, ip)
            m.Lock()
            defer m.Unlock()
            t++
        }(addr, ip)
    }
    swg.Wait()
    return t
}

if target {
    ip, port, _ = str.ParseStringToHostPort(target)
    addr = str.HostPort(ip, port)
    handleCheck(addr, ip)
}

if iptables {
    k = run(iptables)
    yakit.Info("目标总数: %v", k)
}
